class Solution {
    private int visited;
    private int result;

    public int kthSmallest(TreeNode root, int k) {
        visited = 0;
        result = 0;
        traversal(root, k);
        return result;
    }

    private void traversal(TreeNode node, int k) {
        if (node == null || visited == k) {
            return;
        }
        traversal(node.left, k);
        if (visited == k) {
            return; // 左子树已经找到第 k 个
        }
        visited++;
        if (visited == k) {
            result = node.val;
            return;
        }
        traversal(node.right, k);
    }
}

