class Solution {
    private TreeNode next;

    public void flatten(TreeNode root) {
        next = null;
        traversal(root);
    }

    private void traversal(TreeNode node) {
        if (node == null) {
            return;
        }
        // 前序是根、左、右。倒着处理，才能先把后缀接好。
        traversal(node.right);
        traversal(node.left);
        node.right = next;
        node.left = null;
        next = node;
    }
}

